create extension if not exists pgcrypto;
create table if not exists public.categories(id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique,parent_id uuid references public.categories(id) on delete set null,active boolean default true,created_at timestamptz default now());
create table if not exists public.products(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique,description text default '',category_id uuid references public.categories(id) on delete set null,price numeric(12,2) not null default 0,sale_price numeric(12,2),sku text unique,stock integer not null default 0,brand text,weight numeric,dimensions jsonb default '{}'::jsonb,sizes text[] default '{}',colors text[] default '{}',active boolean default true,featured boolean default false,is_new boolean default false,bestseller boolean default false,seo_title text,seo_description text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.product_images(id uuid primary key default gen_random_uuid(),product_id uuid references public.products(id) on delete cascade,url text not null,alt_text text default '',sort_order integer default 0,created_at timestamptz default now());
create table if not exists public.site_content(id uuid primary key default gen_random_uuid(),key text not null unique,value jsonb not null default '{}'::jsonb,updated_at timestamptz default now());
create table if not exists public.orders(id uuid primary key default gen_random_uuid(),customer_name text,customer_email text,customer_phone text,status text default 'pending',subtotal numeric(12,2) default 0,total numeric(12,2) default 0,shipping jsonb default '{}'::jsonb,created_at timestamptz default now());
create table if not exists public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid references public.orders(id) on delete cascade,product_id uuid references public.products(id) on delete set null,product_name text,quantity integer not null,unit_price numeric(12,2) not null,variation jsonb default '{}'::jsonb);
create table if not exists public.store_settings(id uuid primary key default gen_random_uuid(),store_name text default 'VESTE',city text default 'Rio Branco',state text default 'Acre',whatsapp text,email text,phone text,address text,business_hours text,instagram text,updated_at timestamptz default now());
